parameters.jsCode:
// Normalisation et validation des données d'entrée
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;

  // Nettoyage et extraction
  const nom_contact = (body.nom_contact || '').trim();
  const nom_entreprise = (body.nom_entreprise || '').trim();
  const secteur_activite = (body.secteur_activite || 'Non spécifié').trim();
  const ville = (body.ville || 'Abidjan').trim();
  const canal_source = (body.canal_source || 'formulaire_web').trim();
  let telephone = (body.telephone || '').replace(/[^0-9+]/g, '');
  const email = (body.email || '').trim().toLowerCase();
  const besoin_exprime = (body.besoin_exprime || '').trim();

  // Formatage indicatif Côte d'Ivoire (+225) si 10 chiffres locaux
  if (telephone.length === 10 && !telephone.startsWith('+')) {
    telephone = '+225' + telephone;
  }

  // Validation des champs indispensables
  const erreurs = [];
  if (!nom_entreprise && !nom_contact) {
    erreurs.push('Nom du contact ou de l\'entreprise obligatoire');
  }
  if (!telephone && !email) {
    erreurs.push('Au moins un canal de contact (téléphone ou email) est requis');
  }

  const valide = erreurs.length === 0;
  const lead_id = 'LEAD-' + Date.now() + '-' + Math.floor(Math.random() * 1000);

  results.push({
    json: {
      lead_id,
      nom_contact,
      nom_entreprise,
      secteur_activite,
      ville,
      canal_source,
      telephone,
      email,
      besoin_exprime,
      statut_crm: valide ? 'nouveau' : 'a_verifier',
      ne_plus_contacter: false,
      est_valide: valide,
      erreurs_validation: erreurs,
      date_creation: new Date().toISOString()
    }
  });
}

return results;

